def min_stack_ops(operations: list[list]) -> list:
    stack = []
    res = []
    for op in operations:
        if op[0] == 'push':
            val = op[1]
            current_min = min(val, stack[-1][1]) if stack else val
            stack.append((val, current_min))
            res.append(None)
        elif op[0] == 'pop':
            if stack: stack.pop()
            res.append(None)
        elif op[0] == 'top':
            res.append(stack[-1][0] if stack else None)
        elif op[0] == 'get_min':
            res.append(stack[-1][1] if stack else None)
    return res
